// Que horas estan REALMENTE libres, leidas de la agenda.
//
// Por que existe este nodo (2026-08-27). Cuando la hora pedida estaba ocupada,
// al agente se le devolvia una REGLA -- "la nueva hora debe empezar al menos N
// minutos antes o despues" -- y ninguna hora concreta. El agente adivinaba, y
// si la agenda tenia dos o tres citas ese dia adivinaba mal dos o tres veces
// seguidas: "¿las 3?" -> ocupada -> "¿las 4?" -> ocupada. Al cliente le parece
// que el sistema esta roto, y tiene razon.
//
// Se veia sobre todo en la SEGUNDA cita del mismo chat, y no es casualidad: la
// cita que el agente acababa de crear bloquea su colchon a cada lado, que son
// exactamente las horas vecinas que iba a proponer.
//
// Aqui se calcula la lista de horas que de verdad caben, con la misma regla de
// colchon que valida el choque, y se le entrega al agente. El prompt le prohibe
// ofrecer cualquier hora que no venga en esa lista.
const ZONA = 'America/Bogota';
// Se ofrecen horas en punto y y media: es como las ofrece una persona, y con el
// colchon de 30 minutos no tiene sentido una rejilla mas fina.
const PASO_MIN = 30;
const MAX_OPCIONES = 5;

const v = $('Calcular Ventana').first().json;

// Los eventos de dia completo llegan con `start.date` y no `start.dateTime`.
// Se ignoran, igual que hacia el chequeo anterior: son marcas del calendario
// (una fecha de evento apartada, un festivo) y no citas que ocupen una hora.
const eventos = ($input.first().json.items || [])
  .filter((e) => e.start && e.start.dateTime && e.end && e.end.dateTime)
  .map((e) => ({
    inicio: DateTime.fromISO(e.start.dateTime).setZone(ZONA),
    fin: DateTime.fromISO(e.end.dateTime).setZone(ZONA),
  }));

const chocaCon = (desde, hasta) => eventos.some((e) => e.inicio < hasta && e.fin > desde);

// ¿La hora que pidio el cliente choca? Es el mismo criterio de siempre, pero
// calculado aqui sobre la agenda completa en vez de con una consulta aparte.
const choque = chocaCon(
  DateTime.fromISO(v.ventana_inicio).setZone(ZONA),
  DateTime.fromISO(v.ventana_fin).setZone(ZONA),
);

const ahora = DateTime.now().setZone(ZONA);
const pedida = DateTime.fromISO(v.inicio).setZone(ZONA);

// Los huecos de un dia, en orden cronologico.
function huecosDe(dia) {
  const franja = v.horario[dia.weekday];
  if (!franja) return [];                       // domingo: no abre
  const [abre, cierra] = franja;
  const ymd = dia.toFormat('yyyy-MM-dd');
  const cierreDt = DateTime.fromFormat(`${ymd} ${cierra}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  const out = [];
  let t = DateTime.fromFormat(`${ymd} ${abre}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  for (; t.plus({ minutes: v.duracion_min }) <= cierreDt; t = t.plus({ minutes: PASO_MIN })) {
    if (t <= ahora) continue;
    const finT = t.plus({ minutes: v.duracion_min });
    // La misma regla del colchon que decide el choque: si se usara otra, el
    // agente ofreceria horas que el validador rechaza al llamarlo de vuelta.
    if (chocaCon(t.minus({ minutes: v.colchon_min }), finT.plus({ minutes: v.colchon_min }))) continue;
    out.push(t);
  }
  return out;
}

const desde = DateTime.fromISO(v.rango_inicio).setZone(ZONA).startOf('day');
const candidatos = [];

// El dia que pidio el cliente va primero y ordenado por CERCANIA a la hora que
// pidio: si queria las 3 de la tarde, ofrecerle las 10 de la manana es no
// haberlo escuchado. Los dias siguientes van en orden normal.
for (let d = 0; d < v.dias_a_mirar && candidatos.length < MAX_OPCIONES; d++) {
  const dia = desde.plus({ days: d });
  const huecos = huecosDe(dia);
  if (d === 0) huecos.sort((a, b) => Math.abs(a.diff(pedida).toMillis()) - Math.abs(b.diff(pedida).toMillis()));
  for (const t of huecos) {
    candidatos.push(t);
    if (candidatos.length >= MAX_OPCIONES) break;
  }
}

const libres = candidatos.map((t) => ({
  fecha: t.toFormat('yyyy-MM-dd'),
  hora: t.toFormat('HH:mm'),
  legible: t.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm"),
}));

const ocupado = Boolean(v.fuera_horario) || choque;
let mensaje = null;

if (ocupado) {
  const motivo = v.fuera_horario
    ? `No se pudo agendar porque ${v.fuera_horario}.`
    : `No se pudo agendar: ya hay algo ocupando el horario de las ${v.inicio_legible}.`;

  if (libres.length === 0) {
    // Honesto y sin salida inventada: es preferible que el agente lo diga a que
    // ofrezca una hora que no existe.
    mensaje = `${motivo} Y NO queda ningun horario libre en los proximos ${v.dias_a_mirar} dias. ` +
      'No te inventes ninguno. Dile al cliente que la agenda esta llena esos dias, preguntale en que ' +
      'franja le sirve mejor mas adelante y ofrecele que un asesor lo contacte para cuadrarlo.';
  } else {
    const listado = libres.map((l) => `${l.legible} [fecha=${l.fecha} hora=${l.hora}]`).join(' | ');
    mensaje = `${motivo} ESTOS HORARIOS SI ESTAN LIBRES, leidos de la agenda ahora mismo: ${listado}. ` +
      'Ofrecele al cliente DOS o TRES de esos, con naturalidad y en formato de 12 horas (ej. "3:00 p.m."). ' +
      'NO ofrezcas NINGUNA hora que no este en esa lista: las demas estan ocupadas y volverias a quedar mal. ' +
      'Cuando el cliente elija, vuelve a llamar esta herramienta con la fecha y la hora EXACTAS que aparecen ' +
      'entre corchetes. Y no le digas que la hora "se acaba de ocupar": nunca estuvo libre.';
  }
}

return [{ json: { ocupado, choque, libres, mensaje } }];

