  if (d.startsWith('0057')) d = d.slice(4);
  else if (d.startsWith('57') && d.length > 10) d = d.slice(2);
  // Fijo viejo marcado con el 0 de larga distancia: 03XX...
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);

  // Una sola cifra repetida (3333333333, 0000000000) no es un telefono: es
  // alguien probando, o el modelo rellenando el hueco por su cuenta.
  if (/^(\d)\1+$/.test(d)) return { ok: false, motivo: 'basura', vistos: d.length };

  if (d.length !== 10) {
    return { ok: false, motivo: d.length < 10 ? 'corto' : 'largo', vistos: d.length };
  }
  // 3XX celular, 60X fijo. Cualquier otra cosa con 10 digitos no se puede marcar.
  if (!/^3/.test(d) && !/^60[1-8]/.test(d)) {
    return { ok: false, motivo: 'no_colombiano', vistos: d.length };
  }
  return { ok: true, motivo: 'ok', vistos: d.length, e164: '+57' + d, nacional: d };
}

// El mensaje va de vuelta al AGENTE, no al cliente: se redacta como instruccion
// para que sepa exactamente que pedir y como pedirlo. El "sin hacerlo sentir
// mal" no es adorno -- el cliente no se equivoco, se le quedo a medias -- y sin
// esa linea el modelo contesta "el numero que me diste es invalido".
function pedirTelefonoOtraVez(revision, crudo, esLlamada) {
  const comoPedirlo = esLlamada
    ? '"confirmame por fa a que numero te llamo"'
    : '"por fa me confirmas un numero de contacto"';
  const cierre = ' Pideselo de nuevo con calidez y SIN hacerlo sentir mal: que se te corto, o quieres confirmarlo, nunca "lo escribiste mal". Y vuelve a llamarme con el numero completo.';

  if (revision.motivo === 'no_dio') {
    return `Falta el numero de contacto del cliente. Pideselo antes de agendar: ${comoPedirlo}.`;
  }
  if (revision.motivo === 'corto') {
    return `El numero que te dio el cliente ("${crudo}") tiene ${revision.vistos} digitos y en Colombia son 10. Se le quedo a medias.` + cierre;
  }
  if (revision.motivo === 'largo') {
    return `El numero que te dio el cliente ("${crudo}") tiene ${revision.vistos} digitos y en Colombia son 10 (o 12 con el 57 adelante). Le sobran cifras.` + cierre;
  }
  if (revision.motivo === 'basura') {
    return `El numero que te dio el cliente ("${crudo}") es la misma cifra repetida, no es un telefono real.` + cierre;
  }
  return `El numero que te dio el cliente ("${crudo}") tiene 10 digitos pero no empieza por 3 (celular) ni por 60X (fijo), asi que no se puede marcar en Colombia.` + cierre;
}

const entrada = $input.first().json;
const texto = (v) => (v ?? '').toString().trim();

const tipo_cita = texto(entrada.tipo_cita);
const fecha = texto(entrada.fecha);
const hora = texto(entrada.hora);
const detalle = texto(entrada.detalle);
const telefono = texto(entrada.telefono);
const nombre = texto(entrada.nombre);
const telefono_contacto = texto(entrada.telefono_contacto);

// El mensaje va de vuelta al agente, no al cliente: se redacta como
// instruccion para que sepa que corregir y vuelva a llamar la herramienta.
const rechazar = (mensaje) => [{ json: { valido: false, agendada: false, mensaje } }];

if (!TIPOS.includes(tipo_cita)) {
  return rechazar(`tipo_cita invalido: "${tipo_cita}". Debe ser exactamente uno de: ${TIPOS.join(', ')}.`);
}

if (!nombre) {
  return rechazar('Falta el nombre del cliente. Preguntaselo antes de agendar la cita.');
}

// Seguro despues de validar el tipo: aca ya se sabe que existe en MINUTOS.
const { duracion: DURACION_MIN, colchon: COLCHON_MIN } = MINUTOS[tipo_cita];

// El telefono con el que escribe NO sirve para llamar: cuando el cliente tiene
// el numero oculto llega como JID (@lid) o como userId, que no se puede marcar.
// Por eso el numero de contacto se pide siempre, y en las llamadas es critico.
const revision = revisarTelefonoCo(telefono_contacto);
if (!revision.ok) {
  return rechazar(pedirTelefonoOtraVez(revision, telefono_contacto, tipo_cita === 'llamada'));
}

// Formato estricto a proposito: si el modelo manda "manana" o "3pm" hay que
// devolverselo como error, no dejar que Google reciba una fecha inventada.
const inicio = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });

if (!inicio.isValid) {
  return rechazar(`Fecha u hora invalidas: "${fecha} ${hora}". Usa fecha en formato YYYY-MM-DD y hora en formato HH:MM de 24 horas.`);
}

const fin = inicio.plus({ minutes: DURACION_MIN });
const ahora = DateTime.now().setZone(ZONA);

// De aqui en adelante, los motivos de TIEMPO. No cortan: marcan el pedido y
// dejan que Calcular Libres proponga horas que existen de verdad.
let fuera_horario = null;
const franja = HORARIO[inicio.weekday];

if (inicio < ahora) {
  fuera_horario = `la hora que intentaste (${inicio.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm")}) ya paso`;
} else if (!franja) {
  // Unico dia sin franja. Se nombra el dia en vez de decir "cerrado" a secas
  // para que el agente pueda repetirselo al cliente tal cual.
  fuera_horario = 'los domingos no hay atencion';
} else {
  // La cita COMPLETA debe caber en la franja: se valida el fin, no solo el
  // inicio. Si no, una cita de 30 min a las 18:45 terminaria a las 19:15, con
  // el local ya cerrado.
  const [abre, cierra] = franja;
  const apertura = DateTime.fromFormat(`${inicio.toFormat('yyyy-MM-dd')} ${abre}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  const cierreDt = DateTime.fromFormat(`${inicio.toFormat('yyyy-MM-dd')} ${cierra}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  if (inicio < apertura || fin > cierreDt) {
    const ultima = cierreDt.minus({ minutes: DURACION_MIN }).toFormat('HH:mm');
    fuera_horario = `atendemos de ${abre} a ${cierra} de lunes a sabado, jornada continua, y como esa cita dura ${DURACION_MIN} minutos la ultima puede empezar a las ${ultima}`;
  }
}

// Desde que dia se buscan huecos: el que pidio el cliente, o HOY si ese ya paso.
// La consulta a Google se hace una sola vez y trae toda la ventana, para que
// Calcular Libres pueda ofrecer horas de los dias siguientes sin otra llamada.
const desde = DateTime.max(inicio.startOf('day'), ahora.startOf('day'));

return [{
  json: {
    valido: true,
    fuera_horario,
    tipo_cita,
    detalle,
    telefono,
    telefono_contacto: revision.e164,
    telefono_contacto_crudo: telefono_contacto,
    nombre,
    inicio: inicio.toISO(),
    fin: fin.toISO(),
    ventana_inicio: inicio.minus({ minutes: COLCHON_MIN }).toISO(),
    ventana_fin: fin.plus({ minutes: COLCHON_MIN }).toISO(),
    inicio_legible: inicio.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm"),
    duracion_min: DURACION_MIN,
    colchon_min: COLCHON_MIN,
    horario: HORARIO,
    dias_a_mirar: DIAS_A_MIRAR,
    rango_inicio: desde.toISO(),
    rango_fin: desde.plus({ days: DIAS_A_MIRAR }).endOf('day').toISO(),
  },
}];

